In `cmd/entire/cli/strategy/metadata_reconcile.go`, replace the existing `createCherryPickCommit` with the following three functions:

```go
// buildCherryPickCommit constructs a new commit object that cherry-picks
// original onto parent with treeHash. The returned commit is not signed
// and not persisted. Callers can sign it in-place (mutating PGPSignature)
// before calling persistCherryPickCommit.
func buildCherryPickCommit(ctx context.Context, repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (*object.Commit, error) {
	committerName, committerEmail := GetGitAuthorFromRepo(repo)
	now := time.Now()

	return &object.Commit{
		TreeHash:     treeHash,
		ParentHashes: []plumbing.Hash{parent},
		Author:       original.Author,
		Committer: object.Signature{
			Name:  committerName,
			Email: committerEmail,
			When:  now,
		},
		Message: original.Message,
	}, nil
}

// persistCherryPickCommit encodes commit and stores it in the repo. The
// returned hash reflects whatever signature state the commit object holds
// at this moment.
func persistCherryPickCommit(repo *git.Repository, commit *object.Commit) (plumbing.Hash, error) {
	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

// createCherryPickCommit builds, best-effort signs, and persists a cherry-
// picked commit. Used by the metadata-reconcile divergence path.
func createCherryPickCommit(ctx context.Context, repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
	commit, err := buildCherryPickCommit(ctx, repo, treeHash, parent, original)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	checkpoint.SignCommitBestEffort(ctx, commit)
	return persistCherryPickCommit(repo, commit)
}
```

