Add `signLocalCommitsForPush` in `cmd/entire/cli/strategy/push_signing.go`:

```go
// signLocalCommitsForPush fetches the remote-tracking tip for ref, finds
// the local-only commits above it, signs and cherry-picks them onto that
// tip, and advances the local ref to the new signed tip. Caller is then
// expected to do a fast-forward push.
func signLocalCommitsForPush(ctx context.Context, target string, ref plumbing.ReferenceName, stderr io.Writer) error {
	if checkpoint.ShouldSkipPushSigning(ctx) {
		return nil
	}

	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("open repo: %w", err)
	}
	defer repo.Close()

	if err := fetchRemoteTipBestEffort(ctx, target, ref); err != nil {
		logging.Debug(ctx, "fetch for sign-at-push failed; signing all local commits as new",
			slog.String("error", err.Error()))
	}

	localRef, err := repo.Reference(ref, true)
	if err != nil {
		// No local ref yet — nothing to sign or push.
		return nil
	}

	remoteHash := lookupRemoteTip(ctx, repo, target, ref)
	repoPath, err := getRepoPath(repo)
	if err != nil {
		return fmt.Errorf("repo path: %w", err)
	}

	commits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteHash)
	if err != nil {
		return fmt.Errorf("collect commits since remote tip: %w", err)
	}
	if len(commits) == 0 {
		return nil
	}

	newTip, err := signAndPersistCommits(ctx, repo, remoteHash, commits, stderr)
	if err != nil {
		return err
	}

	refsBundle := checkpoint.ResolveCommittedRefs(ctx)
	return AdvanceLocalRef(ctx, repo, refsBundle, ref, newTip)
}

func lookupRemoteTip(ctx context.Context, repo *git.Repository, target string, ref plumbing.ReferenceName) plumbing.Hash {
	if !ref.IsBranch() {
		return plumbing.ZeroHash
	}
	rname := plumbing.NewRemoteReferenceName(target, ref.Short())
	r, err := repo.Reference(rname, true)
	if err != nil {
		logging.Debug(ctx, "no remote-tracking ref; treating all local commits as new",
			slog.String("ref", rname.String()),
			slog.String("error", err.Error()))
		return plumbing.ZeroHash
	}
	return r.Hash()
}

// fetchRemoteTipBestEffort runs the existing fetch helper without erroring
// on failure. The push path itself will surface any real connectivity
// problem; here we just want the freshest remote tip if we can get it.
func fetchRemoteTipBestEffort(ctx context.Context, target string, ref plumbing.ReferenceName) error {
	return fetchAndRebaseRefCommon(ctx, target, ref)
}
```

If the `OpenRepository` helper lives elsewhere in `strategy/`, use whatever helper the existing `refreshMirrorBeforePush` uses — that helper already opens a repo via the same pattern.

